#!/usr/bin/env node
'use strict';

// Ensure release copy belongs to OFFICE-X and tracks the package version.
// Release assets are uploaded by the GitHub workflow and attached beneath the
// release body; their filenames are generated by electron-builder.
const fs = require('node:fs');
const path = require('node:path');

const root = path.join(__dirname, '..');
const version = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8')).version;
const release = fs.readFileSync(path.join(root, 'RELEASE.md'), 'utf8');
const errors = [];

if (!release.includes(`# OFFICE-X v${version}`)) {
  errors.push(`RELEASE.md must identify OFFICE-X v${version}`);
}
if (/munderdiffl\.in|Munder-Difflin-\d|Munder Difflin v\d/i.test(release)) {
  errors.push('RELEASE.md still contains inherited product or artifact branding');
}
if (!release.includes('Installers and checksums are attached to the GitHub Release')) {
  errors.push('RELEASE.md must explain where release artifacts are attached');
}

if (errors.length) {
  console.error(`\n✗ release copy needs attention (${errors.length}):`);
  for (const error of errors) console.error(`  - ${error}`);
  process.exit(1);
}
console.log(`✓ OFFICE-X release copy matches v${version}`);
